// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.context/** * NOUS — Ambient context snapshot. * * Optional context: location (coarse), weather, user activity. Used by * context-aware rules (e.g., "when I get home, dim lights") and persona * personalization ("good morning, the weather looks great today"). * * Privacy contract: *   - All ambient data stays on device *   - Location is coarse (city-level), never precise coordinates *   - User can disable all ambient tracking in Privacy Settings (default OFF) */data class AmbientSnapshot(    /** Coarse location (city name + country). Never precise coordinates. */    val locationSummary: String?,    /** Current temperature in Celsius. */    val temperatureC: Float?,    /** Weather condition (e.g., "sunny", "rain", "snow"). */    val weatherCondition: String?,    /** Detected user activity (still, walking, running, in vehicle, sleeping, meeting). */    val userActivity: UserActivity?,    /** Time of day classification (used for persona greetings). */    val timeOfDay: TimeOfDay,    /** Whether headphones are connected. */    val headphonesConnected: Boolean,    /** Whether device is in landscape orientation. */    val isLandscape: Boolean,    /** Ambient light level in lux (0 = pitch dark; < 10 = dim room). Used by voice module for SLEEPING detection. */    val lightLux: Float? = null,    /** Whether device is face-down (proximity sensor). Used by voice module for SLEEPING detection. */    val isFaceDown: Boolean? = null,    /** Hour of day 0-23. Used by voice module for SLEEPING heuristic. */    val hourOfDay: Int? = null,    /** Whether ringer is silent / DND. Used by voice module for IN_MEETING detection. */    val isRingerSilent: Boolean? = null,    /** Whether calendar has an active event. Used by voice module for IN_MEETING detection. */    val isCalendarBusy: Boolean? = null,) {    /** Heuristic: dark + late night + face-down → likely sleeping. Used by voice prosody. */    fun isLikelySleeping(): Boolean {        val dark = lightLux != null && lightLux < 10f        val lateNight = hourOfDay != null && (hourOfDay == 23 || hourOfDay in 0..6)        val faceDown = isFaceDown == true        return dark && lateNight && faceDown    }    /** Heuristic: silent ringer + calendar busy → likely in a meeting. Used by voice prosody. */    fun isLikelyInMeeting(): Boolean = isRingerSilent == true && isCalendarBusy == true    companion object {        /** Default snapshot — no ambient info available. */        val UNKNOWN = AmbientSnapshot(            locationSummary = null,            temperatureC = null,            weatherCondition = null,            userActivity = null,            timeOfDay = TimeOfDay.NOON,            headphonesConnected = false,            isLandscape = false,        )    }}enum class UserActivity {    STILL,    WALKING,    RUNNING,    IN_VEHICLE,    ON_BICYCLE,    /** User is sleeping (1 AM–6 AM, face-down, dark room). */    SLEEPING,    /** User is in a meeting (calendar busy + silent mode). */    IN_MEETING,    /** Activity unknown — fall back to default prosody. */    UNKNOWN,}enum class TimeOfDay {    EARLY_MORNING,    // 4-7 AM    MORNING,          // 7-11 AM    NOON,             // 11 AM - 2 PM    AFTERNOON,        // 2-5 PM    EVENING,          // 5-8 PM    NIGHT,            // 8-11 PM    LATE_NIGHT,       // 11 PM - 4 AM    ;    companion object {        fun fromHour(hour: Int): TimeOfDay = when (hour) {            in 4..6 -> EARLY_MORNING            in 7..10 -> MORNING            in 11..13 -> NOON            in 14..16 -> AFTERNOON            in 17..19 -> EVENING            in 20..22 -> NIGHT            else -> LATE_NIGHT        }    }}